    "Absolute Security": "أمان مطلق",
    "Your IP and funds are protected at all stages by robust escrow vaults.": "الملكية الفكرية وأموالك محمية في جميع المراحل بواسطة خزائن الضمان المالي القوية.",
    "Frequently Asked Questions": "الأسئلة الشائعة",
    "Answers to common inquiries about workspace operations, payments, and safety.": "أجوبة على الاستفسارات الشائعة حول عمليات مساحة العمل والمدفوعات والسلامة.",
    "General Queries": "استفسارات عامة",
    "How does milestone escrow work?": "كيف يعمل نظام الضمان المالي للمراحل؟",
    "When a project is created, the client deposits project funds into our escrow vault. The funds are securely held and automatically released to the freelancer only after the client reviews and approves the submitted deliverable.": "عند إنشاء مشروع، يودع العميل أموال المشروع في خزينة الضمان المالي الخاصة بنا. يتم الاحتفاظ بالأموال بشكل آمن ويتم تحريرها تلقائيًا للمستقل فقط بعد مراجعة العميل للتسليم المقدم والموافقة عليه.",
    "What is the vetting process for freelancers?": "ما هي عملية الفحص والتدقيق للمستقلين؟",
    "Every freelancer undergoes a background assessment, portfolio review, and optional vetting interviews by our admin team before they can bid on high-tier projects.": "يخضع كل مستقل لتقييم الخلفية، ومراجعة معرض الأعمال، ومقابلات فحص اختيارية من قبل فريق الإدارة لدينا قبل أن يتمكن من تقديم عروض على المشاريع رفيعة المستوى.",
    "How are disputes resolved?": "كيف يتم حل النزاعات؟",
    "If a conflict arises regarding milestone completeness, either party can file a dispute. Our neutral admin mediation team reviews submissions and decides on a fair disbursement.": "إذا نشأ نزاع بشأن اكتمال مرحلة معينة، يمكن لأي من الطرفين رفع نزاع. يقوم فريق وساطة الإدارة المحايد لدينا بمراجعة الطلبات والتقرير بشأن الصرف العادل.",
    "Still have questions?": "لا يزال لديك أسئلة؟",
